/**
 * Loader for the dungeon sprite atlas (0x72 DungeonTileset II, CC0) and the
 * few standalone prop images (jojomod Dungeon Tileset V1, CC0).
 *
 * The atlas JSON is generated by `scripts/build-dungeon-atlas.mjs`; frames are
 * looked up by their pack name (e.g. "wall_mid", "knight_m_idle_anim_f0"),
 * so no source coordinates are hard-coded in game code.
 *
 * Loaded once per page and cached.
 */

export const DUNGEON_ATLAS_IMAGE = "/themes/dungeon/dungeon-tileset.png";
export const DUNGEON_ATLAS_JSON = "/themes/dungeon/dungeon-tileset.json";
export const DUNGEON_PROPS_DIR = "/themes/dungeon/props";

export interface FrameRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface DungeonAtlas {
  image: HTMLImageElement;
  frames: Record<string, FrameRect>;
  animations: Record<string, string[]>;
  /** Standalone prop images keyed by file stem (e.g. "barrel"). */
  props: Record<string, HTMLImageElement>;
}

/** Standalone prop files under DUNGEON_PROPS_DIR (without extension). */
export const DUNGEON_PROP_NAMES = [
  "wall-candle-f0",
  "wall-candle-f1",
  "wall-candle-f2",
  "standing-candle-f0",
  "standing-candle-f1",
  "standing-candle-f2",
  "standing-candle-f3",
  "barrel",
  "globe",
  "blacksmith-anvil",
  "wooden-desk",
  "ink-feather",
] as const;
export type DungeonPropName = (typeof DUNGEON_PROP_NAMES)[number];

interface AtlasJson {
  frames: Record<string, { frame: FrameRect }>;
  animations?: Record<string, string[]>;
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Failed to load image ${src}`));
    img.src = src;
  });
}

let atlasPromise: Promise<DungeonAtlas> | null = null;

/** Load (once) the atlas image, frame table and prop images. */
export function loadDungeonAtlas(): Promise<DungeonAtlas> {
  atlasPromise ??= (async () => {
    const [image, json, ...propImages] = await Promise.all([
      loadImage(DUNGEON_ATLAS_IMAGE),
      fetch(DUNGEON_ATLAS_JSON).then((r) => {
        if (!r.ok) throw new Error(`Atlas JSON HTTP ${r.status}`);
        return r.json() as Promise<AtlasJson>;
      }),
      ...DUNGEON_PROP_NAMES.map((n) => loadImage(`${DUNGEON_PROPS_DIR}/${n}.png`)),
    ]);
    const frames: Record<string, FrameRect> = {};
    for (const [name, entry] of Object.entries(json.frames)) frames[name] = entry.frame;
    const props = Object.fromEntries(
      DUNGEON_PROP_NAMES.map((n, i) => [n, propImages[i]]),
    ) as Record<DungeonPropName, HTMLImageElement>;
    return { image, frames, animations: json.animations ?? {}, props };
  })().catch((err) => {
    atlasPromise = null; // allow a retry on next call
    throw err;
  });
  return atlasPromise;
}
